with open('js/app.js','r',encoding='utf-8') as f: js=f.read()
old = 'function doLogin(){\n  const u=document.getElementById("name").value.trim().toLowerCase();\n  const p=document.getElementById("pass").value;\n  const r=document.getElementById("role").value;\n  if((u==="admin"&&p==="admin123")||(u==="pengurus"&&p==="pengurus123")){\n    document.getElementById("view-login").style.display="none";\n    document.getElementById("main-header").style.display="block";\n    window.currentRole=r;\n    if(r==="pengurus"){\n      document.getElementById("tab-input").style.display="none";\n      document.querySelector(".tabs .tab:first-child").style.display="none";\n      document.getElementById("jamaah-satuan").style.display="none";\n    }\n    showPage("dashboard");\n  }else{\n    alert("Username atau password salah!");\n  }\n}'
new = 'function doLogin(){\n  const u=document.getElementById("name").value.trim().toLowerCase();\n  const p=document.getElementById("pass").value;\n  if(u==="admin"&&p==="admin123"){\n    window.currentRole="admin"; enterApp();\n  }else if(u==="pengurus"&&p==="pengurus123"){\n    window.currentRole="pengurus"; enterApp();\n  }else{\n    alert("Username atau password salah!");\n  }\n}\nfunction enterApp(){\n  document.getElementById("view-login").style.display="none";\n  document.getElementById("main-header").style.display="block";\n  if(window.currentRole==="pengurus"){\n    document.getElementById("tab-input").style.display="none";\n    document.querySelector(".tabs .tab:first-child").style.display="none";\n    document.getElementById("jamaah-satuan").style.display="none";\n    document.getElementById("nav-admin").style.display="none";\n  }else if(window.currentRole==="admin"){\n    document.getElementById("nav-admin").style.display="inline-flex";\n  }\n  showPage("dashboard");\n}\nfunction editPengurusPass(){\n  const np=prompt("Password baru untuk Pengurus (minimal 4 karakter):");\n  if(np&&np.length>=4){ alert("Password pengurus diubah ke: " + np); }\n  else alert("Batal atau terlalu pendek");\n}'
js = js.replace(old, new)
with open('js/app.js','w',encoding='utf-8') as f: f.write(js)
print('Login & admin edit password siap')
